import pyomo.environ as pyo

DATA = {
    "foods": ["brownies", "ice_cream", "cola", "cheesecake"],
    "nutrients": ["calories", "chocolate", "sugar", "fat"],
    # cost per unit (cents)
    "cost": {
        "brownies": 50,
        "ice_cream": 20,
        "cola": 30,
        "cheesecake": 80,
    },
    # content[nutrient][food]
    "content": {
        "calories":  {"brownies": 400, "ice_cream": 200, "cola": 150, "cheesecake": 500},
        "chocolate": {"brownies": 3,   "ice_cream": 2,   "cola": 0,   "cheesecake": 0},
        "sugar":     {"brownies": 2,   "ice_cream": 2,   "cola": 4,   "cheesecake": 4},
        "fat":       {"brownies": 2,   "ice_cream": 4,   "cola": 1,   "cheesecake": 5},
    },
    # minimum daily requirement per nutrient
    "requirement": {
        "calories": 500,
        "chocolate": 6,
        "sugar": 10,
        "fat": 8,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    model.quantity = pyo.Var(model.FOODS, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["cost"][i] * m.quantity[i] for i in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.quantity[i] for i in m.FOODS) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model


